#define NUM_GOTAS 50.

float Gota( vec2 gotaPos, vec2 pos, float a )
{
    vec2 delta = (gotaPos - pos) * 50.;

    delta = vec2
    (
        delta.x * cos(a) + delta.y * sin(a),
        delta.y * cos(a) - delta.x * sin(a)
    );

    delta.y = mix(delta.y, sin(delta.y / 2.), step(0., delta.y) - step(3.1415, delta.y));

    return 1. - length(delta);
}

float Hash( float t )
{
    return fract( sin(t * 346.43 + 1.) * 573.436 );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;

    float ratio = iResolution.x / iResolution.y;
    uv.x *= ratio;

    vec3 col = vec3(0.);

    for (float i = 0.; i < NUM_GOTAS; i++)
    {
        float ft = floor(iTime + i / NUM_GOTAS);
        float t = fract(iTime + i / NUM_GOTAS) * (Hash(i + ft / 2.) * 0.3 + 1.);

        float rotacao = cos(ft / 2.);

        float x = 0.1 * (12. * Hash(i) - 1. + rotacao * t) * ratio;
        float y = 1.05 - t*1.1;

        col += vec3(0.7, 0.8, 1.) * pow(clamp( Gota(uv, vec2(x, y), atan(rotacao * ratio / 10.)) , 0., 1.), 0.5) / 2.;
    }

    fragColor = vec4(col,1.0);
}
